mapper.select:
SELECT l.id, l.biz_date, l.create_time, l.change_type,
       CASE WHEN l.inv_doc_id IS NOT NULL THEN 'INV_DOC' ELSE 'INV_COUNT' END AS doc_type,
       d.kind AS doc_kind, COALESCE(l.inv_doc_id, l.count_id) AS doc_id, l.doc_no,
       l.warehouse_id, w.name AS warehouse_name, l.material_sku_id, l.change_qty, l.balance_qty, l.dye_lot, l.create_by
FROM inv_stock_log l
JOIN bas_warehouse w ON w.id = l.warehouse_id
LEFT JOIN inv_doc d ON d.id = l.inv_doc_id
WHERE true
AND l.warehouse_id = #{q.warehouseId}
AND l.material_sku_id = #{q.materialSkuId}

    AND l.change_type IN #{t}

AND l.biz_date >= #{q.bizDateFrom}
AND l.biz_date <= #{q.bizDateTo}

    AND l.id IN #{id}


    AND (l.doc_no ILIKE '%' || #{q.keyword} || '%' OR l.dye_lot ILIKE '%' || #{q.keyword} || '%'
         OR EXISTS (SELECT 1 FROM bas_material_sku k JOIN bas_material m ON m.id = k.material_id
                    WHERE k.id = l.material_sku_id
                      AND (k.code ILIKE '%' || #{q.keyword} || '%' OR m.name ILIKE '%' || #{q.keyword} || '%')))

ORDER BY l.id DESC
